-- 959: Sand casting gating and riser calculators -- the velocity of the metal in the gating; the riser feeding efficiency named as unverified.
--
-- GENERATED by scripts/generate-sand-casting-calculators-migration.ts from
-- src/modules/bom-items/costing/casting/sand/calculators/sand-casting-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- The gating calculator sized the choke, sprue, runner and ingates but never said how fast the metal moves through them. The velocity is the mould's metal
-- over its pouring time (the flow) over the area it passes through; at the choke it equals the efficiency times sqrt(2 g H) by construction. The riser
-- calculator's 14 % feeding efficiency was labelled a standard rule; a research pass found a source for the modulus factor 1.2 and the height-to-diameter
-- ratio 1.5 but none for the 14 %, so the field is now named an unverified rule and the route says so.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Sand Casting catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Sand Casting - Risers
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Sand Casting - Risers$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Sand Casting - Risers$q$, 'process', 'single', false, true, true, $q$Risers by the modulus method with its feed-volume check (D146): each riser's modulus is the casting's (volume / surface) times a factor, so it freezes after the casting; and the risers hold the metal the casting and they shrink by, of which a riser gives only its feed efficiency. A cylinder cooling through its side and top, the larger of the two sizes. Factor, shape and efficiency are the standard rules, the shrinkage the alloy family's typical value, until the plant sets its own. One riser per ingate.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Risers by the modulus method with its feed-volume check (D146): each riser's modulus is the casting's (volume / surface) times a factor, so it freezes after the casting; and the risers hold the metal the casting and they shrink by, of which a riser gives only its feed efficiency. A cylinder cooling through its side and top, the larger of the two sizes. Factor, shape and efficiency are the standard rules, the shrinkage the alloy family's typical value, until the plant sets its own. One riser per ingate.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Casting Modulus$q$, $q$Casting Modulus (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Casting Volume$q$, $q$Casting Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Density$q$, $q$Density (kg/m³)$q$, $q$number$q$, $q$kg/m³$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Risers$q$, $q$Risers$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Shrinkage (estimate)$q$, $q$Shrinkage (estimate) (%)$q$, $q$number$q$, $q$%$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Riser Modulus Factor (standard rule)$q$, $q$Riser Modulus Factor (standard rule)$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$1.2$q$, 6, false),
    (v_id, $q$Height to Diameter (standard rule)$q$, $q$Height to Diameter (standard rule)$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$1.5$q$, 7, false),
    (v_id, $q$Feed Efficiency (unverified rule)$q$, $q$Feed Efficiency (unverified rule) (%)$q$, $q$calculated$q$, $q$%$q$, NULL, NULL, NULL, $q$14$q$, 8, false),
    (v_id, $q$Riser Modulus$q$, $q$Riser Modulus (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q${Casting Modulus} * {Riser Modulus Factor (standard rule)}$q$, 9, false),
    (v_id, $q$Diameter by Modulus$q$, $q$Diameter by Modulus (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q${Riser Modulus} * (4 * {Height to Diameter (standard rule)} + 1) / {Height to Diameter (standard rule)}$q$, 10, false),
    (v_id, $q$Feed Volume per Riser$q$, $q$Feed Volume per Riser (mm³)$q$, $q$calculated$q$, $q$mm³$q$, NULL, NULL, NULL, $q${Shrinkage (estimate)} * {Casting Volume} / ({Feed Efficiency (unverified rule)} - {Shrinkage (estimate)}) / {Risers}$q$, 11, false),
    (v_id, $q$Diameter by Feeding$q$, $q$Diameter by Feeding (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q$(4 * {Feed Volume per Riser} / (pi * {Height to Diameter (standard rule)})) ^ (1 / 3)$q$, 12, false),
