    (v_id, $q$Riser Weight$q$, $q$Riser Weight (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Risers} * {Riser Volume} / 1e9 * {Density}$q$, 16, false);
